import jax
import jax.numpy as jnp
import flax.linen as nn
from typing import Dict, Any

def _define_hyperparameters():
    """Use same hyperparameters as default for a fair comparison."""
    return {
        'learning_rate': 0.001,
        'hidden_dim': 512, # Will be used as num_filters for the CNN
        'dropout_rate': 0.1,
        'kernel_size': 7 # A common choice for motif detection
    }

class SimpleCNN(nn.Module):
    """A simple 1D CNN for RNA sequence modeling."""
    d_output: int
    task_type: str
    num_filters: int
    kernel_size: int
    dropout_rate: float

    @nn.compact
    def __call__(self, x, deterministic=True):
        # x shape: (batch, seq_len, d_input)

        # 1D Convolution Layer
        # Input shape needs to be (batch, seq_len, features)
        x = nn.Conv(features=self.num_filters, kernel_size=(self.kernel_size,))(x)
        x = nn.relu(x)

        # Global Average Pooling across the sequence length
        x = jnp.mean(x, axis=1) # Shape: (batch, num_filters)

        x = nn.Dropout(rate=self.dropout_rate)(x, deterministic=deterministic)

        # Final Dense layer for prediction
        x = nn.Dense(features=self.d_output)(x)

        if self.task_type == "regression":
            return x.squeeze(-1)  # (batch,)
        else:
            return x  # (batch, d_output) for other tasks

class CNNNetworkWrapper:
    """Wrapper for the CNN model to match the required interface."""

    def __init__(self, d_output, task_type, num_filters, kernel_size, dropout_rate):
        self.network = SimpleCNN(
            d_output=d_output,
            task_type=task_type,
            num_filters=num_filters,
            kernel_size=kernel_size,
            dropout_rate=dropout_rate
        )

    def init(self, rng_key, dummy_input):
        params_key, dropout_key = jax.random.split(rng_key)
        variables = self.network.init({'params': params_key, 'dropout': dropout_key}, dummy_input, deterministic=True)
        return variables['params']

    def apply(self, params, x, deterministic=True, rng_key=None):
        if deterministic:
            return self.network.apply({'params': params}, x, deterministic=True)
        else:
            if rng_key is None:
                rng_key = jax.random.PRNGKey(0)
            return self.network.apply({'params': params}, x, deterministic=False, rngs={'dropout': rng_key})

def create_network(hparams: Dict[str, Any]):
    """Create and return the CNN network."""
    return CNNNetworkWrapper(
        d_output=hparams.get("d_output", 1),
        task_type=hparams.get("task_type", "regression"),
        num_filters=hparams.get("hidden_dim", 512), # Re-using hidden_dim as num_filters
        kernel_size=hparams.get("kernel_size", 7),
        dropout_rate=hparams.get("dropout_rate", 0.1)
    )
